import './realtor-runtime-20261019.mjs';import fs from 'node:fs/promises';import assert from 'node:assert/strict';const{db}=await import('./reply-runtime-20261015.mjs');const{api}=await import('./gta-email-recovery-runtime.mjs');const dir='artifacts/partnership-nudges-20261019';const reviews=JSON.parse(await fs.readFile(dir+'/review.json'));const cross=JSON.parse(await fs.readFile(dir+'/cross-channel.json'));
const plans=[
{id:'31f358be-a4d3-4fcf-b607-fe5fd8ce2d24',channel:'email',subject:'Checking in on staging support',body:'Hi Angela,\n\nJohn from Saturn Star Movers here. Just checking in after our email about your shorter staging pickups and drop-offs. Are you still looking for a moving partner, or have you found a setup that works for you?\n\nIf you’re still exploring options, I’d be happy to work through one typical job with you so we can give you a useful price. No need to commit to a volume of work.\n\nJohn\nSaturn Star Movers\nbusiness@starmovers.ca'},
{id:'021718a1-719b-418d-bd45-430ca9f83164',channel:'sms',body:'Hi, John from Saturn Star Movers here. Just checking back on our staging conversation. I understand the work varies and you can’t guarantee volume. Would it still be useful to price one upcoming job together? If you’re covered for now, no worries at all.'},
{id:'4cc8afed-8003-423b-a7b2-0251a53c1ea5',channel:'sms',body:'Hi, John from Saturn Star Movers here. I know the September 23 installation date has passed—how did everything go? If moving support would be useful for a future London installation, we’d be happy to help. If you already have it covered, no worries at all.'}
];await fs.writeFile(dir+'/send-plan.json',JSON.stringify(plans,null,2));
for(const p of plans){
 const file=dir+'/receipt-'+p.id+'.json';try{await fs.access(file);console.log(JSON.stringify({id:p.id,state:'existing_receipt_no_retry'}));continue;}catch(e){if(e.code!=='ENOENT')throw e;}
 const old=reviews.find(r=>r.contact.id===p.id);const ctx=cross.find(r=>r.name===old.contact.name);const [c]=await db('market_contacts',{id:'eq.'+p.id});assert.equal(c.phone,old.contact.phone);assert.equal(c.email,old.contact.email);
 const peers=await db('market_contacts',{phone:'eq.'+c.phone});assert.deepEqual(peers.map(x=>x.id).sort(),ctx.peers.map(x=>x.id).sort());
 // These reviewed duplicate records belong to the same named business. One message only, in the original conversation; retain every peer's suppression.
 for(const peer of peers){assert(!peer.do_not_contact&&!peer.cross_channel_suppressed_at&&!['dnc','closed_lost'].includes(peer.stage)&&!['opted_out','rejected'].includes(peer.decision));const latest=await db('market_touches',{contact_id:'eq.'+peer.id,order:'created_at.desc',limit:'1'});assert.equal(latest[0]?.id,ctx.threads.find(t=>t.id===peer.id).thread[0]?.id,'Changed partner thread');}
 const sms=await db('sms_messages',{or:`(from_number.eq.${c.phone},to_number.eq.${c.phone})`,order:'created_at.desc',limit:'1'});assert.equal(sms[0]?.id,ctx.sms[0]?.id,'Changed Sales SMS');
 const calls=await db('call_recordings',{phone_number:'eq.'+c.phone,order:'created_at.desc',limit:'1'});assert.equal(calls[0]?.recording_sid,ctx.calls[0]?.recording_sid,'Changed calls');
 if(p.channel==='email'){const peers=await db('market_contacts',{email:'ilike.'+c.email});assert(peers.every(x=>!x.do_not_contact&&!x.cross_channel_suppressed_at&&!x.email_unsubscribed_at&&!['bounced','complained','unsubscribed'].includes(x.email_status)));}
 await fs.writeFile(file,JSON.stringify({state:'reserved_no_blind_retry',at:new Date().toISOString(),plan:p,authorization:'Owner requested gentle contextual nudges to these three partnerships'},null,2),{flag:'wx'});
 let result;try{result=await api('/api/marketing/contacts/'+p.id+'/'+(p.channel==='email'?'send-email':'send-reply'),p.channel==='email'?{sender:'john',subject:p.subject,body:p.body}:{body:p.body,from_number:'+12268870667',media_urls:[]});}catch(e){await fs.writeFile(file,JSON.stringify({state:'failed_or_ambiguous_no_retry',at:new Date().toISOString(),plan:p,error:e.message},null,2));console.log(JSON.stringify({name:c.name,error:e.message}));continue;}
 await fs.writeFile(file,JSON.stringify({state:'provider_response',at:new Date().toISOString(),plan:p,result},null,2));const receipt=result.sid||result.messageId;assert(receipt,'No provider receipt');const touches=await db('market_touches',{contact_id:'eq.'+p.id,direction:'eq.outbound',order:'created_at.desc',limit:'5'});const touch=touches.find(t=>[t.metadata?.twilioSid,t.metadata?.provider_message_id,t.metadata?.messageSid].includes(receipt));assert(touch,'No matching CRM receipt');
 for(const peer of peers)await db('market_contacts',{id:'eq.'+peer.id},'PATCH',{sequence_paused:true,sequence_paused_reason:'Owner requested one gentle contextual nudge; await reply',next_follow_up:null,...(p.channel==='email'?{preferred_channel:'email'}:{})});
 await fs.writeFile(file,JSON.stringify({state:'accepted_crm_verified',at:new Date().toISOString(),plan:p,result,touch_id:touch.id},null,2));console.log(JSON.stringify({name:c.name,channel:p.channel,accepted:true,crm_verified:true}));
}
